                "the buffer must be cleared and reused between iterations");
        assertEquals(1, pool.allocateCount, "the buffer must be recycled between iterations");
        assertEquals(1, pool.closeCount);
        assertSame(sourceListener, source.getReadListener());
        assertEquals(1, sourceConduit.wakeupReadsCalls);
        assertEquals(1, sinkConduit.suspendWritesCalls, "null sink listener means writes are suspended");
        assertNull(sink.getWriteListener());
    }

    @Test
    public void partiallyAcceptedWritesAreRetriedUntilTheBufferIsDrained() {
        TestSourceConduit sourceConduit = new TestSourceConduit().data("abcdef").eof();
        ConduitStreamSourceChannel source = sourceChannel(sourceConduit);
        TestSinkConduit sinkConduit = new TestSinkConduit().withMaxPerWrite(2);
        ConduitStreamSinkChannel sink = sinkChannel(sinkConduit);
        TestByteBufferPool pool = new TestByteBufferPool(6, false);
        RecordingListener sinkListener = new RecordingListener();

        Transfer.initiateTransfer(source, sink, null, sinkListener, null, null, pool);

        assertEquals("abcdef", sinkConduit.writtenAsString(), "all bytes must be written across several calls");
        assertEquals(3, sinkConduit.writeCalls, "the sink accepts at most two bytes per call");
        assertEquals(2, sourceConduit.readCalls, "one read for the data and one for the EOF");
        assertEquals(1, pool.closeCount, "the buffer is empty again, so it must be released");
        assertEquals(1, sourceConduit.suspendReadsCalls, "null source listener means reads are suspended");
        assertEquals(1, sinkConduit.wakeupWritesCalls, "the sink listener must be woken up on completion");
        assertSame(sinkListener, sink.getWriteListener());
        assertNull(source.getReadListener());
    }

