    @Test
    public void partiallyWrittenBufferIsKeptForTheInternalListenerAndBothDirectionsResume() {
        TestSourceConduit sourceConduit = new TestSourceConduit().data("abcdef");
        ConduitStreamSourceChannel source = sourceChannel(sourceConduit);
        TestSinkConduit sinkConduit = new TestSinkConduit().withCapacity(2);
        ConduitStreamSinkChannel sink = sinkChannel(sinkConduit);
        TestByteBufferPool pool = new TestByteBufferPool(8, false);
        RecordingListener sourceListener = new RecordingListener();
        RecordingListener sinkListener = new RecordingListener();

        Transfer.initiateTransfer(source, sink, sourceListener, sinkListener, null, null, pool);

        assertEquals("ab", sinkConduit.writtenAsString(), "only the writable part must reach the sink");
        assertEquals(2, sinkConduit.writeCalls, "second write must report zero bytes accepted");
        assertEquals(1, sourceConduit.readCalls);
        assertEquals(List.of(8), sourceConduit.observedReadRemaining,
                "the first read must see the whole freshly allocated buffer");
        assertEquals(1, pool.allocateCount);
        assertEquals(0, pool.closeCount, "the pending buffer must be handed over to the listener");
        assertEquals(1, pool.openCount());
        assertEquals(1, sinkConduit.resumeWritesCalls, "writes must be resumed because data is pending");
        assertEquals(1, sourceConduit.resumeReadsCalls,
                "reads must be resumed because the buffer is not completely full");
        assertEquals(0, sinkConduit.wakeupWritesCalls);
        assertEquals(0, sourceConduit.wakeupReadsCalls);
        assertNotNull(source.getReadListener());
        assertSame(source.getReadListener(), sink.getWriteListener());
        assertNotSame(sourceListener, source.getReadListener());
        assertNotSame(sinkListener, sink.getWriteListener());
    }

    @Test
    public void completelyFullPendingBufferDoesNotResumeReads() {
        TestSourceConduit sourceConduit = new TestSourceConduit().data("12345678");
        ConduitStreamSourceChannel source = sourceChannel(sourceConduit);
        TestSinkConduit sinkConduit = new TestSinkConduit().withCapacity(0);
        ConduitStreamSinkChannel sink = sinkChannel(sinkConduit);
        TestByteBufferPool pool = new TestByteBufferPool(8, false);
        RecordingListener sinkListener = new RecordingListener();

