        assertEquals(0, sinkConduit.writtenSize(), "the sink accepts nothing");
        assertEquals(1, sinkConduit.writeCalls);
        assertEquals(0, sourceConduit.resumeReadsCalls,
                "a completely full buffer means reads must not be resumed");
        assertEquals(1, sinkConduit.resumeWritesCalls);
        assertEquals(0, pool.closeCount);
        assertEquals(1, pool.openCount(), "the full buffer must be kept for the listener");
        assertNotNull(source.getReadListener());
        assertSame(source.getReadListener(), sink.getWriteListener());
        assertNotSame(sinkListener, sink.getWriteListener());
    }

