    @Test
    public void readFailureIsReportedToTheReadExceptionHandlerAndReleasesBuffer() {
        IOException failure = new IOException("read blew up");
        TestSourceConduit sourceConduit = new TestSourceConduit().fail(failure);
        ConduitStreamSourceChannel source = sourceChannel(sourceConduit);
        TestSinkConduit sinkConduit = new TestSinkConduit();
        ConduitStreamSinkChannel sink = sinkChannel(sinkConduit);
        TestByteBufferPool pool = new TestByteBufferPool(16, false);
        RecordingListener sourceListener = new RecordingListener();
        RecordingListener sinkListener = new RecordingListener();
        RecordingExceptionHandler readHandler = new RecordingExceptionHandler();
        RecordingExceptionHandler writeHandler = new RecordingExceptionHandler();

        Transfer.initiateTransfer(source, sink, sourceListener, sinkListener, readHandler, writeHandler, pool);

        assertEquals(1, readHandler.count, "the read exception handler must be invoked exactly once");
        assertSame(source, readHandler.channel);
        assertSame(failure, readHandler.exception);
        assertEquals(0, writeHandler.count);
        assertEquals(0, sinkConduit.writeCalls);
        assertEquals(1, pool.closeCount, "the buffer must be released on a read failure");
        assertEquals(0, pool.openCount());
        assertNull(source.getReadListener(), "no listener may be installed when the transfer aborts");
        assertNull(sink.getWriteListener());
        assertEquals(0, sourceConduit.resumeReadsCalls);
        assertEquals(0, sourceConduit.wakeupReadsCalls);
        assertEquals(0, sinkConduit.resumeWritesCalls);
    }

    @Test
    public void writeFailureIsReportedToTheWriteExceptionHandlerAndReleasesBuffer() {
        IOException failure = new IOException("write blew up");
        TestSourceConduit sourceConduit = new TestSourceConduit().data("payload");
        ConduitStreamSourceChannel source = sourceChannel(sourceConduit);
        TestSinkConduit sinkConduit = new TestSinkConduit().failingWith(failure);
        ConduitStreamSinkChannel sink = sinkChannel(sinkConduit);
        TestByteBufferPool pool = new TestByteBufferPool(16, false);
        RecordingListener sourceListener = new RecordingListener();
        RecordingListener sinkListener = new RecordingListener();
        RecordingExceptionHandler readHandler = new RecordingExceptionHandler();
        RecordingExceptionHandler writeHandler = new RecordingExceptionHandler();

        Transfer.initiateTransfer(source, sink, sourceListener, sinkListener, readHandler, writeHandler, pool);

        assertEquals(0, readHandler.count);
        assertEquals(1, writeHandler.count, "the write exception handler must be invoked exactly once");
        assertSame(sink, writeHandler.channel);
        assertSame(failure, writeHandler.exception);
        assertEquals(1, sourceConduit.readCalls);
        assertEquals(List.of(16), sourceConduit.observedReadRemaining,
                "the first read must see the whole freshly allocated buffer");
        assertEquals(1, sinkConduit.writeCalls);
        assertEquals(0, sinkConduit.writtenSize());
        assertEquals(1, pool.closeCount, "the buffer must be released on a write failure");
        assertEquals(0, pool.openCount());
        assertNull(source.getReadListener());
        assertNull(sink.getWriteListener());
        assertEquals(0, sourceConduit.resumeReadsCalls);
        assertEquals(0, sinkConduit.resumeWritesCalls);
        assertEquals(0, sourceListener.invocations);
        assertEquals(0, sinkListener.invocations);
    }

