    private static ConduitStreamSourceChannel sourceChannel(TestSourceConduit conduit) {
        return new ConduitStreamSourceChannel(null, conduit);
    }

    private static ConduitStreamSinkChannel sinkChannel(TestSinkConduit conduit) {
        return new ConduitStreamSinkChannel(null, conduit);
    }

    private static final class RecordingListener implements ChannelListener<Channel> {
        private int invocations;

        public void handleEvent(Channel channel) {
            invocations++;
        }
    }

    private static final class RecordingExceptionHandler implements ChannelExceptionHandler<Channel> {
        private int count;
        private Channel channel;
        private IOException exception;

        public void handleException(Channel channel, IOException exception) {
            this.count++;
            this.channel = channel;
            this.exception = exception;
        }
    }

    private static final class TestByteBufferPool implements ByteBufferPool {
        private final int bufferSize;
        private final boolean direct;
        private final List<TestPooledByteBuffer> buffers = new ArrayList<>();
        private int allocateCount;
        private int closeCount;

        TestByteBufferPool(int bufferSize, boolean direct) {
            this.bufferSize = bufferSize;
            this.direct = direct;
        }

        public PooledByteBuffer allocate() {
            allocateCount++;
            TestPooledByteBuffer pooled = new TestPooledByteBuffer(this,
                    direct ? ByteBuffer.allocateDirect(bufferSize) : ByteBuffer.allocate(bufferSize));
            buffers.add(pooled);
            return pooled;
        }

        public ByteBufferPool getArrayBackedPool() {
            return this;
        }

        public void close() {
            // nothing to do
        }

        public int getBufferSize() {
            return bufferSize;
        }

        public boolean isDirect() {
            return direct;
        }

        int openCount() {
            int open = 0;
            for (TestPooledByteBuffer buffer : buffers) {
                if (buffer.isOpen()) {
                    open++;
                }
            }
            return open;
        }

        void bufferClosed(TestPooledByteBuffer buffer) {
            closeCount++;
        }
    }

    private static final class TestPooledByteBuffer implements PooledByteBuffer {
        private final TestByteBufferPool pool;
        private final ByteBuffer buffer;
        private boolean open = true;

        TestPooledByteBuffer(TestByteBufferPool pool, ByteBuffer buffer) {
            this.pool = pool;
            this.buffer = buffer;
        }

        public ByteBuffer getBuffer() {
            return buffer;
        }

        public void close() {
            if (open) {
                open = false;
                pool.bufferClosed(this);
            }
        }

        public boolean isOpen() {
            return open;
        }
    }

    /**
     * Source conduit with a scripted sequence of read results. Once the script is exhausted the
     * conduit behaves like an end-of-stream channel.
     */
    private static final class TestSourceConduit implements StreamSourceConduit {
        private final Deque<Object> script = new ArrayDeque<>();
        private final List<Integer> observedReadRemaining = new ArrayList<>();

        private int readCalls;
        private int resumeReadsCalls;
        private int suspendReadsCalls;
        private int wakeupReadsCalls;
        private boolean readResumed;
        private boolean readShutdown;
        private ReadReadyHandler readReadyHandler;

        TestSourceConduit data(String value) {
            script.add(value.getBytes(StandardCharsets.UTF_8));
            return this;
        }

        TestSourceConduit zero() {
            script.add(Integer.valueOf(0));
            return this;
        }

        TestSourceConduit eof() {
            script.add(Integer.valueOf(-1));
            return this;
        }

        TestSourceConduit fail(IOException failure) {
            script.add(failure);
            return this;
        }

        @Override
        public int read(ByteBuffer dst) throws IOException {
            readCalls++;
            observedReadRemaining.add(dst.remaining());
            Object step = script.poll();
            if (step == null) {
                return -1;
            }
            if (step instanceof byte[]) {
                byte[] data = (byte[]) step;
                if (data.length > dst.remaining()) {
                    throw new IllegalStateException("scripted read of " + data.length
                            + " bytes does not fit into the remaining buffer space " + dst.remaining());
                }
                dst.put(data);
                return data.length;
            }
            if (step instanceof IOException) {
                throw (IOException) step;
            }
            return ((Integer) step).intValue();
        }

        @Override
        public long read(ByteBuffer[] dsts, int offs, int len) throws IOException {
            long total = 0;
            for (int i = offs; i < offs + len; i++) {
                int res = read(dsts[i]);
                if (res == -1) {
                    return total == 0 ? -1 : total;
                }
                total += res;
                if (res == 0) {
                    break;
                }
            }
            return total;
        }

        @Override
        public long transferTo(long position, long count, FileChannel target) throws IOException {
            return 0;
        }

        @Override
        public long transferTo(long count, ByteBuffer throughBuffer, StreamSinkChannel target) throws IOException {
            return 0;
        }

        @Override
        public void terminateReads() {
            readShutdown = true;
        }

        @Override
        public boolean isReadShutdown() {
            return readShutdown;
        }

        @Override
        public void resumeReads() {
            resumeReadsCalls++;
            readResumed = true;
        }

        @Override
        public void suspendReads() {
            suspendReadsCalls++;
            readResumed = false;
        }

        @Override
        public void wakeupReads() {
            wakeupReadsCalls++;
            readResumed = true;
        }

        @Override
        public boolean isReadResumed() {
            return readResumed;
        }

        @Override
        public void awaitReadable() {
        }

        @Override
        public void awaitReadable(long time, TimeUnit timeUnit) {
        }

        @Override
        public XnioIoThread getReadThread() {
            return null;
        }

        @Override
        public void setReadReadyHandler(ReadReadyHandler handler) {
            this.readReadyHandler = handler;
        }

        @Override
        public XnioWorker getWorker() {
            return null;
        }
    }

    /**
     * Sink conduit that records everything written to it, optionally imposing a total capacity
     * (after which {@link #write(ByteBuffer)} reports zero bytes accepted) or failing with an
     * {@link IOException}.
     */
    private static final class TestSinkConduit implements StreamSinkConduit {
        private final ByteArrayOutputStream written = new ByteArrayOutputStream();

        private int capacity = Integer.MAX_VALUE;
        private int maxPerWrite = Integer.MAX_VALUE;
        private IOException failure;

        private int writeCalls;
        private int resumeWritesCalls;
        private int suspendWritesCalls;
        private int wakeupWritesCalls;
        private boolean writeResumed;
        private boolean writeShutdown;
        private WriteReadyHandler writeReadyHandler;

        TestSinkConduit withCapacity(int capacity) {
            this.capacity = capacity;
            return this;
        }

        TestSinkConduit withMaxPerWrite(int maxPerWrite) {
            this.maxPerWrite = maxPerWrite;
            return this;
        }

        TestSinkConduit failingWith(IOException failure) {
            this.failure = failure;
            return this;
        }

        String writtenAsString() {
            return new String(written.toByteArray(), StandardCharsets.UTF_8);
        }

        int writtenSize() {
            return written.size();
        }

        @Override
        public int write(ByteBuffer src) throws IOException {
            writeCalls++;
            if (failure != null) {
                throw failure;
            }
            int writable = Math.min(maxPerWrite, Math.max(0, capacity - written.size()));
            int count = Math.min(src.remaining(), writable);
            if (count == 0) {
                return 0;
            }
            byte[] bytes = new byte[count];
            src.get(bytes);
            written.write(bytes, 0, count);
            return count;
        }

        @Override
        public long write(ByteBuffer[] srcs, int offs, int len) throws IOException {
            long total = 0;
            for (int i = offs; i < offs + len; i++) {
                int res = write(srcs[i]);
                total += res;
                if (res == 0) {
                    break;
                }
            }
            return total;
        }


        @Override
        public int writeFinal(ByteBuffer src) throws IOException {
            return write(src);
        }

        @Override
        public long writeFinal(ByteBuffer[] srcs, int offs, int len) throws IOException {
            return write(srcs, offs, len);
        }


        @Override
        public long transferFrom(FileChannel src, long position, long count) throws IOException {
            return 0;
        }

        @Override
        public long transferFrom(StreamSourceChannel source, long count, ByteBuffer throughBuffer)
                throws IOException {
            return 0;
        }

        @Override
        public void terminateWrites() {
            writeShutdown = true;
        }

        @Override
        public boolean isWriteShutdown() {
            return writeShutdown;
        }

        @Override
        public void resumeWrites() {
            resumeWritesCalls++;
            writeResumed = true;
        }

        @Override
        public void suspendWrites() {
            suspendWritesCalls++;
            writeResumed = false;
        }

        @Override
        public void wakeupWrites() {
            wakeupWritesCalls++;
            writeResumed = true;
        }

        @Override
        public boolean isWriteResumed() {
            return writeResumed;
        }

        @Override
        public void awaitWritable() {
        }

        @Override
        public void awaitWritable(long time, TimeUnit timeUnit) {
        }

        @Override
        public XnioIoThread getWriteThread() {
            return null;
        }

        @Override
        public void setWriteReadyHandler(WriteReadyHandler handler) {
            this.writeReadyHandler = handler;
        }

        @Override
        public void truncateWrites() {
            writeShutdown = true;
        }

        @Override
        public boolean flush() {
            return true;
        }

        @Override
        public XnioWorker getWorker() {
            return null;
        }
    }
